Use map to fit models

fit_ols &lt;- function(df) {
    lm(lifeExp ~ log(gdpPercap), data = df)
}

out_tidy = nested_gap |&gt; 
    mutate(model = map(data, fit_ols),
           tidied = map(model, tidy))  |&gt; 
    unnest(tidied, .drop = TRUE)  |&gt; 
    filter(term != "(Intercept)" &
           continent != "Oceania")

out_tidy

How to make these plots in R

prcomp and scale
retx keyword calcualtes embeddings


aus_fit = aus_athletes |&gt; 
  select(where(is.numeric))  |&gt;  
  prcomp(scale = TRUE)

# or
# gets rid of mean and rescales variance

aus_fit = aus_athletes |&gt; 
  select(where(is.numeric))  |&gt;  
  scale() |&gt; 
  prcomp(retx = TRUE)

Interpreting Clusters

Takes some tricky to understand code to transform the PCA coordinates:


wine_df_2 = wine_df |&gt; select(-Type)
centers_df = t(t(wine_clusters$centers %*% t(pca_fit$rotation)) *
            pca_fit$scale + pca_fit$center) |&gt; 
  as_tibble() |&gt; 
  bind_rows(wine_df_2) |&gt; 
  scale() |&gt; 
  as_tibble() |&gt; 
  head(n=3) |&gt;
  mutate(center = seq(1:3))


